use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// 9999-12-31T23:59:59Z: the last instant whose date fits in YYYY-MM-DD.
const MAX_SECONDS: u64 = 253_402_300_799;

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

/// Days since 1970-01-01 to (year, month, day), proleptic Gregorian.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let secs = seconds.min(MAX_SECONDS);
    let days = (secs / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment lookup (approved grant extension). The result does not
        // affect the output; a transport failure is returned as a value and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _enrichment = http_client::fetch(&url);

        let now = wall_clock::now();
        let date = format_date(now.seconds);

        RunInfo {
            date,
            started: now.seconds,
        }
    }
}

export!(Node);
